def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])

    # The most frequent color is the background.
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # Find a full-length, uniform divider.
    hr = next((r for r in range(h)
               if g[r][0] != bg and all(v == g[r][0] for v in g[r])), None)
    vertical = hr is None
    if not vertical:
        divider = hr
        cells = [(r, c) for r in range(h) if r != divider
                 for c in range(w) if g[r][c] not in (bg, g[divider][0])]
    else:
        divider = next((c for c in range(w)
                        if g[0][c] != bg and all(g[r][c] == g[0][c] for r in range(h))), None)
        if divider is None:
            return g
        cells = [(r, c) for r in range(h) for c in range(w)
                 if c != divider and g[r][c] not in (bg, g[0][divider])]

    if not cells:
        return g

    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    obj = [[g[r][c] for c in range(c0, c1 + 1)]
           for r in range(r0, r1 + 1)]
    for r, c in cells:
        g[r][c] = bg

    if not vertical:
        if r0 < divider:
            nr0, marker = divider - len(obj), divider - len(obj) - 1
        else:
            nr0, marker = divider + 1, divider + 1 + len(obj)
        if 0 <= marker < h:
            g[marker] = [8] * w
        for i, row in enumerate(obj):
            for j, val in enumerate(row):
                g[nr0 + i][c0 + j] = val
    else:
        if c0 < divider:
            nc0, marker = divider - len(obj[0]), divider - len(obj[0]) - 1
        else:
            nc0, marker = divider + 1, divider + 1 + len(obj[0])
        if 0 <= marker < w:
            for r in range(h):
                g[r][marker] = 8
        for i, row in enumerate(obj):
            for j, val in enumerate(row):
                g[r0 + i][nc0 + j] = val

    return g
